"""Compose an OLED replay from a contribution snake generated by Platane/snk."""

from collections import Counter
from hashlib import sha1
from pathlib import Path
import re
import xml.etree.ElementTree as ET
from xml.sax.saxutils import quoteattr


_GLYPHS = {
    "D": ("11110", "11001", "11001", "11001", "11001", "11001", "11110"),
    "O": ("01110", "11011", "11011", "11011", "11011", "11011", "01110"),
    "N": ("10001", "11001", "11001", "10101", "10011", "10011", "10001"),
    "G": ("01111", "11000", "11000", "11011", "11001", "11001", "01111"),
}


def _title_path():
    return "".join(
        f"M{letter * 6 + col} {row}h.92v.92h-.92z"
        for letter, char in enumerate("DONG")
        for row, bits in enumerate(_GLYPHS[char])
        for col, bit in enumerate(bits)
        if bit == "1"
    )


def _source_file():
    base = Path(__file__).resolve().parent
    for place in (base.parent, base, base.parent.parent / "profile"):
        candidate = place / "assets" / "contribution-snake-dark.svg"
        if candidate.is_file():
            return candidate
    raise FileNotFoundError("Pass a Platane/snk SVG as source=path")


def _rect(elem):
    attrs = " ".join(f"{key}={quoteattr(value)}" for key, value in elem.attrib.items())
    return f"<rect {attrs}/>"


def _hit_times(css, cells):
    """Each lit-day rule reaches the empty color on the frame that consumes it."""
    counts = Counter(c.attrib["class"].split()[1] for c in cells if len(c.attrib["class"].split()) == 2)
    hits = Counter()
    for name, body in re.findall(r"@keyframes\s+(\w+)\{((?:[^{}]*\{[^{}]*\})*)\}", css):
        if name not in counts:
            continue
        empty_frame = re.search(r"([\d.]+)%(?:,[\d.]+%)*\{fill:var\(--ce\)\}", body)
        if empty_frame:
            hits[float(empty_frame[1])] += counts.pop(name)
    if counts:
        raise ValueError("Unrecognized snk food keyframes")
    return hits


def screen(x, y, w, h, theme="dark", compact=False, source=None, still=False):
    """Return a nested SVG. All four coordinates are in the parent SVG's units.

    Pass the freshly generated snake file as source in a standalone project.
    Compact screens with room for two rows wrap the calendar at a week boundary.
    Setting the outer SVG's --replay-state to 'paused' pauses all replay animations.
    still=True exports an unconditional static initial frame for README picture sources.
    """
    if w <= 0 or h <= 0:
        raise ValueError("screen width and height must be positive")
    root = ET.parse(source or _source_file()).getroot()
    ns = root.tag.partition("}")[0] + "}"
    css = root.findtext(ns + "style", "")
    elements = root.findall(ns + "rect")
    groups = {k: [e for e in elements if e.get("class", "").split()[:1] == [k]] for k in ("c", "s", "u")}
    cells = groups["c"]
    cols = sorted({float(e.get("x")) for e in cells})
    step = cols[1] - cols[0] if len(cols) > 1 else 16
    right = step * len(cols)
    height = max(float(e.get("y")) for e in cells) - min(float(e.get("y")) for e in cells) + step
    hits = _hit_times(css, cells)
    total = sum(hits.values())
    duration = re.search(r"animation:[^{}]*?(\d+)ms", css)
    if not duration:
        raise ValueError("Could not read snk replay duration")
    duration = int(duration[1])
    prefix = "oled" + sha1(f"{x}:{y}:{w}:{h}:{theme}:{int(compact)}:{duration}:{still}".encode()).hexdigest()[:9]
    scoped = re.sub(r":root\{[^{}]*\}", "", css, count=1)
    scoped = re.sub(r"(?<![\w.-])\.(?=[cus](?:\.|\{))", f".{prefix} .", scoped)
    scoped = re.sub(r"(@keyframes\s+|animation-name:)([a-z0-9]+)", rf"\g<1>{prefix}_\2", scoped)
    vheight = 520 * h / w
    wrap = compact and vheight >= 235 and len(cols) >= 24
    inks = ("#152b30", "#388e7f", "#45bba2", "#77dcb0", "#c8ffa6")
    if theme == "light":
        inks = ("#162b30", "#478b87", "#4db4a9", "#93d8ac", "#d6f9ab")
    pal = ";".join(f"--c{i}:{color}" for i, color in enumerate(inks))
    bg_id, clip_id = prefix + "bg", prefix + "slot"
    left, plot_w = 17, 486
    title_scale = min(6.65, max(2.85, vheight * (.021 if wrap else .027)))
    heading_y = 13 if vheight < 135 else 17
    footer_y = vheight - 10
    header_bottom = heading_y + 7 * title_scale + 12
    footer_top = footer_y - 15
    slots = sum(hits.values()) + 1
    score = 0
    score_frames = ["0%{transform:translateY(0px)}"]
    for when, n in sorted(hits.items()):
        score += n
        score_frames.append(f"{when:g}%{{transform:translateY(-{score * 23}px)}}")
    score_frames.append(f"100%{{transform:translateY(-{score * 23}px)}}")
    score_y = heading_y + 7 * title_scale - 1
    digits = max(2, len(str(total)))
    digit_w = 12 * digits + 3
    score_x = 501 - 12 * (digits + 1) - digit_w
    counter = "".join(
        f'<text x="0" y="{i*23}" fill="#d6ffce" font-size="19" font-weight="700">{i:0{digits}d}</text>'
        for i in range(slots)
    )
    grid = "".join(_rect(e) for e in cells)
    snake = "".join(_rect(e) for e in groups["s"])
    gauge = "".join(_rect(e) for e in groups["u"])
    # Both windows replay the same source. Only the visible coordinate range changes.
    ranges = [(0, right)]
    if wrap:
        middle = step * ((len(cols) + 1) // 2)
        ranges = [(0, middle), (middle, right)]
    row_h = (footer_top - header_bottom) / len(ranges)
    board = []
    for idx, (start, end) in enumerate(ranges):
        world_y = -step * 1.13
        world_h = height + step * 1.26
        top = header_bottom + idx * row_h
        # The second window begins on a week boundary. Keep a constant week pitch.
        scale = plot_w / max(b - a for a, b in ranges)
        px_w = (end - start) * scale
        px_h = min(row_h - 3, world_h * scale * 1.10)
        px_x = left
        px_y = top + (row_h - px_h)/2
        board.append(f'<svg x="{px_x:.3f}" y="{px_y:.3f}" width="{px_w:.3f}" height="{px_h:.3f}" '
                     f'viewBox="{start:g} {world_y:g} {end-start:g} {world_h:g}" preserveAspectRatio="none" overflow="hidden">'
                     f'{grid}{snake}<g class="s s0" pointer-events="none">'
                     '<path d="M4 4h2.8v2.8H4zM9 4h2.8v2.8H9z" fill="#183833"/></g></svg>')
    gauge_y = float(groups["u"][0].get("y")) if groups["u"] else 144
    css_extra = f"""
.{prefix}{{--ce:{inks[0]};--cb:#234047;--cs:#d4ff9a;{pal}}}
.{prefix} text{{font-family:Consolas,'DejaVu Sans Mono',monospace}}
.{prefix} .s.s1{{fill:#a7f5aa}}.{prefix} .s.s2{{fill:#72dca6}}.{prefix} .s.s3{{fill:#4dbda8}}
.{prefix} .c,.{prefix} .s,.{prefix} .u,.{prefix} .scores{{animation-play-state:var(--replay-state,running)}}
@keyframes {prefix}_score{{{''.join(score_frames)}}}
.{prefix} .scores{{animation-name:{prefix}_score;animation-duration:{duration}ms;animation-timing-function:steps(1,end);animation-iteration-count:infinite}}
@media(prefers-reduced-motion:reduce){{.{prefix} .c,.{prefix} .s,.{prefix} .u,.{prefix} .scores{{animation:none}}}}
"""
    if still:
        # Embedded SVGs do not inherit the outer document's motion setting in every viewer.
        css_extra += f".{prefix} .c,.{prefix} .s,.{prefix} .u,.{prefix} .scores{{animation:none!important}}"
        scoped = re.sub(r"@keyframes\s+[\w-]+\{(?:[^{}]*\{[^{}]*\})*\}", "", scoped)
    return f'''<svg x="{x}" y="{y}" width="{w}" height="{h}" viewBox="0 0 520 {vheight:.4f}" class="{prefix}" overflow="hidden" role="img" aria-label="公开贡献日历的贪吃蛇回放，共有 {total} 个贡献日。">
<defs><linearGradient id="{bg_id}" x2=".9" y2="1"><stop stop-color="#061113"/><stop offset=".53" stop-color="#0b1a20"/><stop offset="1" stop-color="#0a141a"/></linearGradient>
<clipPath id="{clip_id}"><rect x="-1" y="-16" width="{digit_w}" height="20"/></clipPath>
<style>{scoped}{css_extra}</style></defs>
<rect width="520" height="{vheight:.4f}" rx="5" fill="url(#{bg_id})"/>
<path d="{_title_path()}" transform="translate({left} {heading_y}) scale({title_scale})" fill="#c9ffab"/>
<path d="M{left} {header_bottom-3:.2f}H503" stroke="#2b454a" stroke-width=".85"/>
<text x="{score_x-10}" y="{score_y:.3f}" text-anchor="end" font-size="11" letter-spacing="1.2" fill="#82aaab">DAYS</text>
<g transform="translate({score_x} {score_y:.3f})"><g clip-path="url(#{clip_id})"><g class="scores">{counter}</g></g></g>
<text x="503" y="{score_y:.3f}" text-anchor="end" font-size="19" fill="#87aca2">/{total:0{digits}d}</text>
{''.join(board)}
<path d="M{left} {footer_top-1.5:.3f}H503" stroke="#2b454a" stroke-width=".85"/>
<path d="M17 {footer_y-7:.2f}l7 4-7 4z" fill="#a7f5ab"/><text x="32" y="{footer_y+1:.2f}" fill="#86aca6" font-size="10.5" letter-spacing="1.5">SNAKE REPLAY</text>
<rect x="151" y="{footer_y-5.1:.3f}" width="352" height="4.2" rx="1" fill="#21363a"/>
<svg x="151" y="{footer_y-5.1:.3f}" width="352" height="4.2" viewBox="0 {gauge_y:g} {right:g} 12" preserveAspectRatio="none" overflow="hidden">{gauge}</svg>
</svg>'''
